export const BOOK_PARTS=[
 {key:'understand',ids:['glance','why','people']},
 {key:'experience',ids:['experience','apps','onboarding','journey','qr']},
 {key:'operate',ids:['team','operations','admin-demo','principles','trust','architecture']},
 {key:'build',ids:['business','growth','roadmap','workshop','partnership']},
 {key:'brand',ids:['rami','rami-expressions','rami-careers','rami-goods','rami-identity']},
 {key:'scope',ids:['faq']}
];
export function orderedChapters(book,rami,additional=[]){const all=[...book.sections,...rami,...additional];return BOOK_PARTS.flatMap(part=>part.ids.map(id=>all.find(s=>s.id===id))).filter(Boolean);}
const keys=['headline','intro','start','read','badge','scope','groups','details','mapTitle','mapHead','mapRows'];
const rows={
ko:["사장님의 사업 파트너,\nAI 에이전트 라미.","사장님이 샵을 소개하면, 라미가 손님을 맞고 주문과 예약을 돕습니다. 말이 다른 손님에게도 우리 샵을 편하게 소개할 수 있는 방법을 함께 만들어갑니다.",'통합 시연 보기','원샵 알아보기','지금은 준비된 데모예요 · 실제 AI와 결제는 미연결','현재 기능 범위',['원샵 이야기','직접 체험해요','함께 샵을 운영해요','앞으로의 계획','라미와 브랜드','지금 가능한 것'],['주문·통역 과정만 살펴보기','메뉴 등록과 QR 발급만 살펴보기','사장님 로그인·복구 과정 살펴보기'],'지금 체험할 수 있는 것',['구분','체험할 수 있는 일','데이터와 연결 범위'],[
['프로덕션북 통합 시연','메뉴 등록부터 주문·예약·배달, 직원의 처리와 손님 알림까지','가입 없이 바로 볼 수 있는 준비된 이야기입니다. 새로고침하면 체험 기록이 지워집니다.'],
['별도 손님·사장님·직원 앱','샵과 메뉴를 저장하고, 다른 휴대폰에서 주문·예약과 직원 처리를 체험합니다.','연결된 샵의 기록이 저장됩니다. 사장님은 비밀번호로, 직원은 발급받은 링크로 들어갑니다.'],
['출시 전에 연결·검증할 것','실제 AI, 메뉴 사진 인식, 결제·POS, 메일 복구·외부 알림','아직 연결되지 않았습니다. 직원 본인 인증과 현지 언어 검수도 출시 전에 준비해야 합니다.']]],
en:["Meet Rami, your AI agent\nand business partner.","From guest conversations to orders, reservations and shop operations, Rami is ready to help. With one shop, creating an AI agent tailored to your business is simple.",'Try the full demo','Explore the essentials','A project book demo with no live AI or payments','Current capabilities',['Understand one shop','Try the experience','Run the shop together','Prepare the business and launch','Rami and the brand','Scope and references'],['Explore ordering and interpretation only','Explore menu registration and QR creation','Explore owner login and recovery'],'What you can try today',['Experience','What you can do','Data and connections'],[
['Integrated book demo','Menu setup, multilingual orders, bookings, delivery and change agreements across four roles','A prepared scenario with no sign-up. Reloading resets the demonstration records.'],
['Separate guest, owner and staff apps','Save shop menus, take orders and bookings from another phone, and sync role-based handling','Connected shop records are stored on the server. Owners use a password; staff use issued links.'],
['To connect and verify before launch','Live AI, menu photo recognition, payments, POS, email recovery and external notifications','Not connected yet. Verified staff identity and local-language review are also launch tasks.']]],
vi:["Rami, trợ lý AI\nđồng hành cùng chủ quán.","Từ trò chuyện với khách, nhận đơn, đặt bàn đến quản lý quán, Rami luôn sẵn sàng hỗ trợ. Với one shop, bạn dễ dàng tạo trợ lý AI phù hợp với công việc kinh doanh của mình.",'Thử toàn bộ quy trình','Xem điểm chính','Sách dự án demo, chưa kết nối AI và thanh toán thật','Phạm vi hiện tại',['Hiểu về one shop','Trải nghiệm trực tiếp','Cùng vận hành quán','Chuẩn bị kinh doanh và ra mắt','Rami và thương hiệu','Phạm vi và tài liệu'],['Chỉ xem gọi món và phiên dịch','Chỉ xem đăng thực đơn và tạo QR','Xem đăng nhập và khôi phục của chủ quán'],'Những gì có thể thử hôm nay',['Trải nghiệm','Bạn có thể làm gì','Dữ liệu và kết nối'],[
['Trình diễn tích hợp trong sách','Đăng thực đơn, gọi món đa ngôn ngữ, đặt bàn, giao hàng và thống nhất thay đổi giữa bốn vai trò','Chạy theo kịch bản mẫu, không cần đăng ký. Tải lại trang sẽ xóa dữ liệu trình diễn.'],
['Ứng dụng khách, chủ quán và nhân viên riêng','Lưu quán và thực đơn, nhận đơn và đặt bàn từ điện thoại khác, đồng bộ xử lý theo vai trò','Dữ liệu quán đã kết nối lưu trên máy chủ. Chủ quán dùng mật khẩu; nhân viên dùng liên kết được cấp.'],
['Cần kết nối và kiểm chứng trước ra mắt','AI thật, nhận diện ảnh thực đơn, thanh toán, POS, khôi phục email và thông báo ngoài ứng dụng','Chưa kết nối. Xác minh nhân viên và kiểm duyệt ngôn ngữ tại địa phương cũng cần hoàn thành trước ra mắt.']]],
zh:["您的生意伙伴，\nAI 智能助手拉米。","从接待顾客、处理订单和预约到店铺运营，拉米随时为您提供帮助。通过 one shop，您可以轻松创建适合自己生意的 AI 智能助手。",'体验完整演示','了解核心内容','项目书演示，未连接真实AI或支付','当前功能范围',['了解one shop','亲自体验','协作运营','准备业务与上线','拉米与品牌','功能范围与参考'],['仅体验点单与翻译','仅体验菜单登记与QR生成','体验店主登录与找回密码'],'现在可以体验什么',['体验','可体验内容','数据与连接'],[
['项目书集成演示','菜单登记、多语言订单、预约、配送及四角色的变更协商','无需注册的预设场景。刷新页面会清空演示记录。'],
['独立客人、店主及员工应用','保存店铺与菜单，从其他手机下单或预约，按角色处理并同步','已连接店铺的记录保存在服务器。店主使用密码，员工使用专属链接。'],
['上线前需连接与验证','真实AI、菜单照片识别、支付、POS、邮件找回及外部通知','尚未连接。员工身份验证和各语言的本地审核也是上线前任务。']]],
ja:["お店の頼れるパートナー、\nAIエージェントのラミ。","お客様との会話から注文・予約、店舗運営まで。one shopでラミと出会い、お店にぴったりのAIエージェントを簡単につくれます。",'統合デモを試す','要点を見る','実際のAI・決済を使わないプロジェクトブック','現在の対応範囲',['one shopを知る','実際に体験する','一緒に店舗を運営する','事業と公開の準備','ラミとブランド','対応範囲と参考資料'],['注文と通訳だけを試す','メニュー登録とQR発行だけを試す','オーナーのログイン・復旧を試す'],'今、体験できること',['体験','できること','データと接続範囲'],[
['ブックの統合デモ','メニュー登録、多言語注文・予約・配達、4つの役割による変更の合意','登録不要の準備済みシナリオです。再読み込みでデモ記録は初期化されます。'],
['別のお客様・オーナー・スタッフアプリ','店舗とメニューの保存、別のスマホから注文・予約、役割別の処理と同期','接続した店舗の記録をサーバーに保存します。オーナーはパスワード、スタッフは発行されたリンクで利用します。'],
['公開前に接続・検証すること','実際のAI、メニュー写真認識、決済・POS、メール復旧・外部通知','現在は未接続です。スタッフ本人確認と言語ごとの現地レビューも公開前の課題です。']]],
km:["Rami ជាជំនួយការ AI\nដែលរួមដំណើរជាមួយម្ចាស់ហាង។","ពីការនិយាយជាមួយភ្ញៀវ ការទទួលបញ្ជាទិញ និងកក់ រហូតដល់ការគ្រប់គ្រងហាង Rami ត្រៀមជួយអ្នក។ ជាមួយ one shop អ្នកអាចបង្កើតជំនួយការ AI ដែលសមនឹងអាជីវកម្មរបស់អ្នកបានយ៉ាងងាយស្រួល។",'សាកល្បងដំណើរការទាំងមូល','មើលចំណុចសំខាន់','សៀវភៅគម្រោងសាកល្បង មិនភ្ជាប់ AI ឬទូទាត់ពិត','មុខងារបច្ចុប្បន្ន',['ស្គាល់ one shop','សាកល្បងផ្ទាល់','គ្រប់គ្រងហាងរួមគ្នា','ត្រៀមអាជីវកម្មនិងដាក់ប្រើ','Rami និងម៉ាក','វិសាលភាពនិងឯកសារយោង'],['មើលតែការបញ្ជាទិញនិងបកប្រែ','មើលតែការចុះម៉ឺនុយនិងបង្កើត QR','មើលការចូលនិងស្ដាររបស់ម្ចាស់ហាង'],'អ្វីដែលអាចសាកល្បងថ្ងៃនេះ',['បទពិសោធន៍','អ្វីដែលអាចធ្វើ','ទិន្នន័យនិងការភ្ជាប់'],[
['ការបង្ហាញរួមក្នុងសៀវភៅ','ចុះម៉ឺនុយ បញ្ជាទិញច្រើនភាសា កក់ ដឹកជញ្ជូន និងព្រមព្រៀងកែប្រែតាមតួនាទីបួន','ដំណើរការតាមគំរូ មិនត្រូវការចុះឈ្មោះ។ ផ្ទុកទំព័រឡើងវិញនឹងលុបកំណត់ត្រាសាកល្បង។'],
['កម្មវិធីភ្ញៀវ ម្ចាស់ហាង និងបុគ្គលិកដាច់ដោយឡែក','រក្សាហាងនិងម៉ឺនុយ ទទួលបញ្ជាទិញនិងកក់ពីទូរស័ព្ទផ្សេង និងធ្វើសមកាលកម្មតាមតួនាទី','កំណត់ត្រាហាងដែលភ្ជាប់រក្សាលើម៉ាស៊ីនមេ។ ម្ចាស់ប្រើពាក្យសម្ងាត់ បុគ្គលិកប្រើតំណដែលបានផ្ដល់។'],
['ត្រូវភ្ជាប់និងផ្ទៀងផ្ទាត់មុនដាក់ប្រើ','AI ពិត ស្គាល់រូបម៉ឺនុយ ទូទាត់ POS ស្ដារតាមអ៊ីមែល និងជូនដំណឹងខាងក្រៅ','មិនទាន់ភ្ជាប់។ ការបញ្ជាក់អត្តសញ្ញាណបុគ្គលិកនិងពិនិត្យភាសាមូលដ្ឋានក៏ត្រូវធ្វើមុនដាក់ប្រើ។']]],
id:["Rami, agen AI\nmitra usaha Anda.","Dari melayani tamu, menerima pesanan dan reservasi hingga mengelola kedai, Rami siap membantu. Bersama one shop, Anda dapat membuat agen AI yang sesuai dengan usaha Anda dengan mudah.",'Coba demo lengkap','Lihat inti one shop','Buku proyek demo tanpa AI atau pembayaran nyata','Cakupan saat ini',['Kenali one shop','Coba pengalamannya','Kelola kedai bersama','Siapkan bisnis dan peluncuran','Rami dan merek','Cakupan dan referensi'],['Coba pesanan dan penerjemahan saja','Coba pendaftaran menu dan QR saja','Coba login dan pemulihan pemilik'],'Yang bisa dicoba sekarang',['Pengalaman','Yang dapat dilakukan','Data dan koneksi'],[
['Demo terpadu dalam buku','Pendaftaran menu, pesanan multibahasa, reservasi, pengantaran, dan kesepakatan perubahan empat peran','Skenario siap pakai tanpa pendaftaran. Memuat ulang halaman mereset catatan demo.'],
['Aplikasi tamu, pemilik, dan staf terpisah','Simpan kedai dan menu, terima pesanan dari ponsel lain, sinkronkan penanganan sesuai peran','Catatan kedai yang terhubung disimpan di server. Pemilik memakai kata sandi; staf memakai tautan yang diberikan.'],
['Perlu dihubungkan dan diverifikasi sebelum rilis','AI nyata, pembacaan foto menu, pembayaran, POS, pemulihan email, dan notifikasi eksternal','Belum terhubung. Verifikasi identitas staf dan pemeriksaan bahasa lokal juga perlu diselesaikan sebelum rilis.']]],
lo:["Rami ຜູ້ຊ່ວຍ AI\nຄູ່ຄິດຂອງເຈົ້າຂອງຮ້ານ.","ຕັ້ງແຕ່ສົນທະນາກັບລູກຄ້າ ຮັບອໍເດີ ຮັບຈອງ ໄປຈົນເຖິງການຈັດການຮ້ານ Rami ພ້ອມຊ່ວຍທ່ານ. ກັບ one shop ທ່ານສ້າງຜູ້ຊ່ວຍ AI ທີ່ເໝາະກັບທຸລະກິດໄດ້ຢ່າງງ່າຍດາຍ.",'ລອງຂັ້ນຕອນທັງໝົດ','ເບິ່ງຈຸດສຳຄັນ','ປຶ້ມໂຄງການສາທິດ ບໍ່ເຊື່ອມ AI ຫຼືຊຳລະຈິງ','ຂອບເຂດປັດຈຸບັນ',['ຮູ້ຈັກ one shop','ລອງໃຊ້ໂດຍກົງ','ຮ່ວມກັນດຳເນີນຮ້ານ','ກຽມທຸລະກິດແລະເປີດໃຊ້','Rami ແລະແບຣນ','ຂອບເຂດແລະເອກະສານ'],['ເບິ່ງສະເພາະສັ່ງແລະແປພາສາ','ເບິ່ງສະເພາະລົງເມນູແລະ QR','ເບິ່ງການເຂົ້າແລະກູ້ບັນຊີເຈົ້າຂອງ'],'ສິ່ງທີ່ລອງໄດ້ຕອນນີ້',['ການທົດລອງ','ສິ່ງທີ່ເຮັດໄດ້','ຂໍ້ມູນແລະການເຊື່ອມ'],[
['ການສາທິດລວມໃນປຶ້ມ','ລົງເມນູ ສັ່ງຫຼາຍພາສາ ຈອງ ຈັດສົ່ງ ແລະຕົກລົງປ່ຽນໃນສີ່ບົດບາດ','ໃຊ້ສະຖານະການທີ່ກຽມໄວ້ ບໍ່ຕ້ອງສະໝັກ. ໂຫຼດໜ້າໃໝ່ຈະລ້າງບັນທຶກສາທິດ.'],
['ແອັບລູກຄ້າ ເຈົ້າຂອງ ແລະພະນັກງານແຍກ','ເກັບຮ້ານແລະເມນູ ຮັບອໍເດີຈາກມືຖືອື່ນ ແລະຊິງຕາມບົດບາດ','ບັນທຶກຮ້ານທີ່ເຊື່ອມແລ້ວເກັບຢູ່ເຊີບເວີ. ເຈົ້າຂອງໃຊ້ລະຫັດ ພະນັກງານໃຊ້ລິ້ງທີ່ອອກໃຫ້.'],
['ຕ້ອງເຊື່ອມແລະກວດກ່ອນເປີດ','AI ຈິງ ອ່ານຮູບເມນູ ຊຳລະ POS ກູ້ຜ່ານອີເມວ ແລະແຈ້ງເຕືອນພາຍນອກ','ຍັງບໍ່ເຊື່ອມ. ການຢືນຢັນພະນັກງານແລະກວດພາສາທ້ອງຖິ່ນກໍເປັນວຽກກ່ອນເປີດ.']]],
hi:["रामि, आपका AI एजेंट\nऔर कारोबार का साथी।","ग्राहकों से बातचीत, ऑर्डर और बुकिंग से लेकर दुकान के कामकाज तक, रामि मदद के लिए तैयार है। one shop पर अपने कारोबार के लिए सही AI एजेंट आसानी से बनाएँ।",'पूरा डेमो आज़माएँ','मुख्य बातें देखें','असली AI और भुगतान के बिना प्रोजेक्ट बुक डेमो','मौजूदा सुविधाएँ',['one shop को जानें','खुद आज़माएँ','मिलकर दुकान चलाएँ','व्यवसाय और लॉन्च की तैयारी','Rami और ब्रांड','दायरा और संदर्भ'],['सिर्फ ऑर्डर और अनुवाद देखें','सिर्फ मेन्यू जोड़ना और QR देखें','मालिक का लॉगिन और रिकवरी देखें'],'आज क्या आज़मा सकते हैं',['अनुभव','क्या कर सकते हैं','डेटा और जुड़ाव'],[
['पुस्तक का एकीकृत डेमो','मेन्यू जोड़ना, कई भाषाओं में ऑर्डर, आरक्षण, डिलीवरी और चार भूमिकाओं में बदलाव पर सहमति','तैयार परिदृश्य, पंजीकरण की ज़रूरत नहीं। पेज दोबारा लोड करने पर डेमो रिकॉर्ड रीसेट होंगे।'],
['अलग मेहमान, मालिक और कर्मचारी ऐप','दुकान व मेन्यू सहेजना, दूसरे फोन से ऑर्डर और आरक्षण, भूमिका के अनुसार काम और सिंक','जुड़ी दुकान का रिकॉर्ड सर्वर पर रहता है। मालिक पासवर्ड और कर्मचारी जारी लिंक इस्तेमाल करते हैं।'],
['लॉन्च से पहले जोड़ना और जाँचना है','असली AI, मेन्यू फोटो पहचान, भुगतान, POS, ईमेल रिकवरी और बाहरी सूचनाएँ','अभी जुड़े नहीं हैं। कर्मचारियों की पहचान और स्थानीय भाषाओं की समीक्षा भी लॉन्च से पहले ज़रूरी है।']]]
};
export const EDITORIAL_COPY=Object.fromEntries(Object.entries(rows).map(([lang,row])=>[lang,Object.fromEntries(keys.map((key,i)=>[key,row[i]]))]));
export function capabilityTable(lang){const c=EDITORIAL_COPY[lang];return `<div class="capability-map"><table><caption>${esc(c.mapTitle)}</caption><thead><tr>${c.mapHead.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${c.mapRows.map(([name,what,boundary])=>`<tr><th scope="row">${esc(name)}</th><td>${esc(what)}</td><td>${esc(boundary)}</td></tr>`).join('')}</tbody></table></div>`;}
